import{_ as a,o,c as r,a2 as l}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"6.3 导线截面的选择","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-3-dao-xian-jie-mian-de-xuan-ze.md","filePath":"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-3-dao-xian-jie-mian-de-xuan-ze.md","lastUpdated":1793095197000}'),i={name:"electrician/low-voltage-electrician/06-chapter-6-dao-xian-dian-lan-yu-di-ya-xian-lu/6-3-dao-xian-jie-mian-de-xuan-ze.md"};function e(d,t,n,s,h,u){return o(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="_6-3-导线截面的选择" tabindex="-1">6.3 导线截面的选择 <a class="header-anchor" href="#_6-3-导线截面的选择" aria-label="Permalink to &quot;6.3 导线截面的选择&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>选导线不是&quot;越粗越好&quot;(贵、浪费),也不是&quot;越细越好&quot;(发热危险)。这一节讲选截面的<strong>三个条件</strong>:载流量(发热)、电压损失、机械强度——按这个顺序一步步校核。</p><h2 id="一、选择截面必须满足的三个条件" tabindex="-1">一、选择截面必须满足的三个条件 <a class="header-anchor" href="#一、选择截面必须满足的三个条件" aria-label="Permalink to &quot;一、选择截面必须满足的三个条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条件</th><th>解决什么问题</th><th>核心原则</th></tr></thead><tbody><tr><td><strong>载流量(发热条件)</strong></td><td>导线通电发热不超允许值</td><td>导线允许电流 ≥ 负载电流</td></tr><tr><td><strong>电压损失</strong></td><td>线路末端电压不能降太多</td><td>电压损失 ≤ 允许值(一般 ≤ 5%)</td></tr><tr><td><strong>机械强度</strong></td><td>导线不会被拉断、碰断</td><td>截面 ≥ 最小允许截面</td></tr></tbody></table><blockquote><p>💡 选择顺序:<strong>先按载流量选,再校电压损失,最后验机械强度</strong>——取三者中的较大截面。</p></blockquote><h2 id="二、按载流量选择-发热条件" tabindex="-1">二、按载流量选择(发热条件) <a class="header-anchor" href="#二、按载流量选择-发热条件" aria-label="Permalink to &quot;二、按载流量选择(发热条件)&quot;">​</a></h2><p><strong>载流量</strong>:导线在允许温度下长期通过的最大电流。截面越大,载流量越大。</p><h3 id="铝芯绝缘导线载流量口诀-常考" tabindex="-1">铝芯绝缘导线载流量口诀(常考) <a class="header-anchor" href="#铝芯绝缘导线载流量口诀-常考" aria-label="Permalink to &quot;铝芯绝缘导线载流量口诀(常考)&quot;">​</a></h3><blockquote><p><strong>&quot;二点五下乘以九,往上减一顺号走;三十五乘三点五,双双成组减点五。&quot;</strong></p></blockquote><p>用大白话拆解(铝芯、明敷、25℃条件):</p><table tabindex="0"><thead><tr><th>截面积(mm²)</th><th>口诀</th><th>载流量约(A)</th></tr></thead><tbody><tr><td>2.5 及以下</td><td>×9</td><td>2.5×9 ≈ 22</td></tr><tr><td>4</td><td>×8</td><td>32</td></tr><tr><td>6</td><td>×7</td><td>42</td></tr><tr><td>10</td><td>×6</td><td>60</td></tr><tr><td>16</td><td>×5</td><td>80</td></tr><tr><td>25</td><td>×4</td><td>100</td></tr><tr><td>35</td><td>×3.5</td><td>≈ 122</td></tr><tr><td>50/70</td><td>×3(双双成组)</td><td>150/210</td></tr></tbody></table><blockquote><p>💡 口诀是<strong>经验速算</strong>,适用于铝芯绝缘线明敷。铜芯载流量约为同截面铝芯的 1.3 倍左右;穿管、高温等条件要打折扣。</p></blockquote><p><strong>选用判断</strong>:所选导线的允许载流量<strong>必须大于或等于</strong>线路的计算电流。</p><h2 id="三、按电压损失校验" tabindex="-1">三、按电压损失校验 <a class="header-anchor" href="#三、按电压损失校验" aria-label="Permalink to &quot;三、按电压损失校验&quot;">​</a></h2><p>导线长、截面小,线路电阻大,电流通过时压降大,负载端电压偏低(灯发暗、电动机转不动)。</p><ul><li>低压线路电压损失一般不超过 <strong>5%</strong>;</li><li>线路越长、电流越大,需要的截面越大。</li></ul><h2 id="四、按机械强度校验" tabindex="-1">四、按机械强度校验 <a class="header-anchor" href="#四、按机械强度校验" aria-label="Permalink to &quot;四、按机械强度校验&quot;">​</a></h2><p>导线太细容易被拉断、在安装中损坏。不同用途有<strong>最小允许截面</strong>要求:</p><ul><li>绝缘导线配线、固定敷设:一般不小于 1.5 mm²(铜);</li><li>架空线路、易受力的场合:要求更大截面;</li><li>移动式设备引线:要用软线且截面足够。</li></ul><h2 id="五、综合判断举例" tabindex="-1">五、综合判断举例 <a class="header-anchor" href="#五、综合判断举例" aria-label="Permalink to &quot;五、综合判断举例&quot;">​</a></h2><p><strong>例题</strong>:一条低压线路负载电流 30 A,应选多大铝芯绝缘导线?</p><p><strong>解</strong>:</p><ol><li>查口诀:6 mm² 铝线载流量约 42 A,4 mm² 约 32 A;</li><li>选 4 mm² 载流量 32 A &gt; 30 A,勉强可行,但若线路较长还需校验电压损失;</li><li>若线路较长,可加大到 6 mm²,兼顾电压损失和余量;</li><li>最后校验机械强度(固定敷设铜/铝线最小截面满足即可)。</li></ol><blockquote><p>💡 工程上习惯<strong>留余量</strong>选大一号,并考虑穿管降容。</p></blockquote><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 选截面的三个条件:<strong>载流量、电压损失、机械强度</strong>。</li><li>✅ 口诀&quot;二点五下乘以九&quot;(铝芯绝缘线载流量速算)。</li><li>✅ 所选导线载流量 ≥ 负载电流。</li><li>✅ 电压损失一般不超过 5%。</li><li>⚠️ 易混点:口诀针对<strong>铝芯</strong>线;铜芯载流量约为铝芯的 1.3 倍。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>先按载流量(发热)、再校电压损失、后验机械强度。</li><li>载流量口诀快速估算铝芯线允许电流。</li><li>实际选用留余量,考虑敷设条件和线路长度。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)导线截面的选择,应优先按载流量(发热)条件确定,再校验电压损失和机械强度。( )</li><li>(单选)铝芯绝缘导线载流量口诀&quot;二点五下乘以九&quot;,指 2.5 mm² 及以下的导线载流量约为截面积的()倍。 A. 5　B. 7　C. 9　D. 3</li><li>(判断)低压线路的电压损失一般不应超过 5%。( )</li><li>(单选)同样截面下,铜芯导线的载流量约为铝芯导线的()倍左右。 A. 0.7　B. 1.3　C. 2　D. 3</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。三个条件按&quot;载流量→电压损失→机械强度&quot;顺序校核。</li><li><strong>C</strong>。2.5 mm² 及以下载流量约为截面积的 9 倍。</li><li><strong>√</strong>。电压损失一般不超过 5%。</li><li><strong>B</strong>。铜芯载流量约为铝芯的 1.3 倍。</li></ol></details>',32)])])}const m=a(i,[["render",e]]);export{g as __pageData,m as default};
